/* custom function for NWC for adding page headers */
(function () {

  function removeExistingHeader() {
    var existing = document.querySelector('.src-section-header');
    if (existing) existing.remove();
  }

  function buildHeader(title, subtitle) {
    var header = document.createElement('div');
    header.className = 'src-section-header';
    header.innerHTML =
      '<div class="src-section-header__title">' + title + '</div>' +
      (subtitle ? '<div class="src-section-header__subtitle">' + subtitle + '</div>' : '');
    return header;
  }

  function findFirstQuestionNode() {
    return (
      document.querySelector('.cf-question') ||
      document.querySelector('[data-question-id]') ||
      document.querySelector('.question') ||
      null
    );
  }

  function insertHeaderIntoPage(header) {
    var firstQuestion = findFirstQuestionNode();
    if (firstQuestion && firstQuestion.parentNode) {
      // ✅ Insert as part of page content, before question
      firstQuestion.parentNode.insertBefore(header, firstQuestion);
      return;
    }

    // Fallback (rare)
    var content =
      document.querySelector('.cf-page__content') ||
      document.querySelector('main') ||
      document.body;

    content.insertBefore(header, content.firstChild);
  }

  function renderHeaderIfSet() {
    var title = sessionStorage.getItem('SRC_HDR_TITLE');
    if (!title) return; // No section header set yet

    var subtitle = sessionStorage.getItem('SRC_HDR_SUBTITLE') || '';

    removeExistingHeader();
    insertHeaderIntoPage(buildHeader(title, subtitle));
  }

function runWhenReady(tries) {
  tries = tries || 0;

  // If the question DOM exists, render now
  if (findFirstQuestionNode()) {
    renderHeaderIfSet();
    return;
  }

  // Otherwise retry briefly (Forsta often builds DOM right after global JS runs)
  if (tries < 20) {
    setTimeout(function () { runWhenReady(tries + 1); }, 50);
  } else {
    // last resort: render anyway
    renderHeaderIfSet();
  }
}

runWhenReady();

})();



// We have to generate a key for the timestamp submission for each page. We do this by combining the ids of the 
// individual questions.
// time stamp without idle time
function getPageId() {
    let questions;
    try {
        questions = window.Confirmit.page.questions;
    } catch(e) {
        //console.debug("window.Confirmit.page.questions object could not be found.");
        return "timestamp_error_default";
    }
   
    const questionNames = questions.map(q => q?.id)
    for (let name of questionNames) {
        if (!name || String(name).length < 1) {
            //console.debug("missing question id");
            return "timestamp_error_default";
        }
    }

    return questionNames.join("-");
}
 
 
document.addEventListener("DOMContentLoaded", () => {
    createIdleAwareTimer({
        idleThresholdSeconds: 60,
        tickIntervalMs: 1000,
        onActiveTick: createActiveTimeRecorder("pageTime")
    }).start();
});

function createActiveTimeRecorder(variableName) {
    let activeSeconds = 0;
    const startTime = (new Date()).toISOString();
    const pageId = getPageId();

    return () => {
        activeSeconds += 1;
        syncServerTime(variableName, JSON.stringify({
            pageId,
            startTime,
            activeSeconds
        }));
    };
}

function syncServerTime(variableName, newValue) {
    // This two step is required because once a serverVariable is created via `.add()`, 
    // subsequent calls to `.add()` will silently do nothing (value will not get updated)
    Confirmit.page.serverVariables.add(variableName, newValue);
    Confirmit.page.serverVariables.edit(variableName, newValue);
    console.log("New server time is: " + Confirmit.page.serverVariables.get(variableName));
}

function createIdleAwareTimer({ idleThresholdSeconds, tickIntervalMs, onActiveTick }) {
    let idleSeconds = 0;
    let intervalId = null;
    let eventsAttached = false;

    const resetIdle = () => {
        idleSeconds = 0;
    };

    const stop = () => {
        if (intervalId !== null) {
            clearInterval(intervalId);
            intervalId = null;
        }
    };

    const tick = () => {
        if (idleSeconds < idleThresholdSeconds) {
            onActiveTick();
        }
        idleSeconds += 1;
    };

    const start = () => {
        attachEvents();
        stop();
        intervalId = window.setInterval(tick, tickIntervalMs);
    };

    const attachEvents = () => {
        if (eventsAttached) return;
        eventsAttached = true;

        document.addEventListener("click", resetIdle);
        document.addEventListener("mousemove", resetIdle);
        document.addEventListener("keydown", resetIdle);

        window.addEventListener("blur", stop);
        window.addEventListener("focus", start);
    };

    return { start, stop };
}

