Multi.StartupScript:
(function () {
    var root = document.getElementById("S3");
    if (!root) return;
    //console.log("S3 JS loaded");
    //console.log("root found?", !!root, root);


    var NOTE_TEXT = "Please re-enter";

    // Store old values in JS memory (not the DOM)
    var oldValueMap = new WeakMap();


    // Tracks whether the respondent has started interacting on THIS visit
    var userInteracted = false;
    root.addEventListener("input", function () { userInteracted = true; }, true);
    root.addEventListener("change", function () { userInteracted = true; }, true);
    // root.addEventListener("keydown", function () { userInteracted = true; }, true);


    // Check if values already exist in inputs right now
    function valuesExistNow() {
        var fields = root.querySelectorAll("input, textarea");
        for (var i = 0; i < fields.length; i++) {
            if ((fields[i].value || "").trim() !== "") return true;
        }
        return false;
    }


    // Latch: once true, never goes back to false
    var backtrackMode = false;

    // Decide backtrack mode only if they haven't interacted yet
    function tryEnableBacktrackMode() {
        if (backtrackMode) return;
        // if (!seenBefore) return;          // first ever show in this tab
        if (userInteracted) return;       // they started typing on this visit -> not a backtrack show
        if (valuesExistNow()) backtrackMode = true;  // values are prefilled -> true backtrack
    }

    // Run checks a few times to catch RR hydration delays
    tryEnableBacktrackMode();
    setTimeout(tryEnableBacktrackMode, 50);
    setTimeout(tryEnableBacktrackMode, 200);
    setTimeout(tryEnableBacktrackMode, 500);
    // DEBUG: expose internal flags to console (remove when done)
    // window.__S3_seenBefore = seenBefore;
    // window.__S3_backtrackMode = backtrackMode;
    // window.__S3_userInteracted = userInteracted;

    // ---------- Mask rules ----------
    function maskName(val) {
        val = (val || "").toString();
        var firstKept = false;
        var out = "";
        for (var i = 0; i < val.length; i++) {
            var ch = val[i];
            if (!firstKept && ch.trim() !== "") {
                out += ch;
                firstKept = true;
            } else {
                out += (/[A-Za-z0-9]/.test(ch) ? "*" : ch);
            }
        }
        return out.trim() ? out : "";
    }

    function maskEmail(val) {
        val = (val || "").toString().trim();
        if (!val) return "";
        var at = val.indexOf("@");
        if (at === -1) return maskName(val);
        var local = val.slice(0, at);
        var domain = val.slice(at);
        var first = local.slice(0, 1) || "*";
        return first + "***" + domain; // j***@gmail.com
    }

    // Phone: stars + last 3 digits
    function maskPhone(val) {
        var digits = (val || "").toString().replace(/\D+/g, "");
        if (!digits) return "";
        if (digits.length <= 3) return "*".repeat(digits.length);
        return "*".repeat(digits.length - 3) + digits.slice(-3);
    }

    function shouldMask(el) {
        var id = el.id || "";
        var m = id.match(/S3_(\d+)_input$/);
        if (m) {
            var idx = parseInt(m[1], 10) - 1;

            // Only mask fields 7, 8, and 9 (6,7,8 if 0-based)
            return idx >= 6 && idx <= 8;
        }

        return false;
    }


    // ---------- Identify which field is which ----------
    function classifyField(el) {
        // Preferred: S3_1_input..S3_5_input (your project is 1-based)
        var id = el.id || "";
        var m = id.match(/S3_(\d+)_input$/);
        if (m) {
            var n = parseInt(m[1], 10) - 1; // normalize to 0-based
            // 6 = Phone | 7 = Email | 8 = name
            // if (n === 0 || n === 1) return "name";
            if (n === 6) return "phone";
            if (n === 7) return "email";
        }
        return "name";
    }

    function getMasked(kind, realVal) {
        if (!realVal || !realVal.trim()) return "";
        if (kind === "email") return maskEmail(realVal);
        if (kind === "phone") return maskPhone(realVal);
        return maskName(realVal);
    }

    // ---------- Wrap helpers ----------
    function ensureWrap(el) {
        // already in shell?
        if (el.parentElement && el.parentElement.classList.contains("field-shell")) {
            return el.parentElement.parentElement; // mask-wrap
        }

        var wrap = document.createElement("div");
        wrap.className = "mask-wrap";

        var shell = document.createElement("div");
        shell.className = "field-shell";

        el.parentNode.insertBefore(wrap, el);
        wrap.appendChild(shell);
        shell.appendChild(el);

        return wrap;
    }

    function ensureNote(el, wrap) {
        //if (el.getAttribute("data-was-populated") !== "1") return null;

        var note = wrap.querySelector(".reenter-note");
        if (!note) {
            note = document.createElement("div");
            note.className = "reenter-note";
            note.textContent = NOTE_TEXT;
            wrap.appendChild(note);
        }
        return note;
    }

    function showNote(el) {
        // if (el.getAttribute("data-was-populated") !== "1") return;
        var wrap = ensureWrap(el);
        var note = ensureNote(el, wrap);
        if (note) note.classList.add("is-visible");
    }

    function hideNote(el) {
        var wrap = el.closest(".mask-wrap");
        if (!wrap) return;
        var note = wrap.querySelector(".reenter-note");
        if (note) note.classList.remove("is-visible");
    }

    function copyInputStylesToOverlay(input, overlay) {
        var cs = window.getComputedStyle(input);
        overlay.style.font = cs.font;
        overlay.style.fontSize = cs.fontSize;
        overlay.style.fontFamily = cs.fontFamily;
        overlay.style.fontWeight = cs.fontWeight;
        overlay.style.lineHeight = cs.lineHeight;
        overlay.style.paddingTop = cs.paddingTop;
        overlay.style.paddingRight = cs.paddingRight;
        overlay.style.paddingBottom = cs.paddingBottom;
        overlay.style.paddingLeft = cs.paddingLeft;

        if (input.tagName === "TEXTAREA") overlay.style.alignItems = "flex-start";
    }

    // ---------- Mask / Unmask ----------
    function removeMask(el) {
        el.classList.remove("masked-value");
        var wrap = el.closest(".mask-wrap");
        if (!wrap) return;
        var shell = wrap.querySelector(".field-shell") || wrap;
        var overlay = shell.querySelector(".masked-overlay");
        if (overlay) overlay.remove();
    }

    function isInvalid(el) {
        var question = el.closest(".cf-question");
        if (!question) return false;

        return question.querySelector(".cf-question_error") !== null;
    }

    function applyMask(el) {
        if (!backtrackMode) return;      // never mask on first entry    
        if (!shouldMask(el)) return; // skip no‑mask fields
        if (isInvalid(el)) return;       // validation wins

        if (el.getAttribute("data-typed") === "1") return;


        var real = (el.value || "").toString();
        if (!real.trim()) {
            el.removeAttribute("data-was-populated");
            removeMask(el);
            return;
        }

        // mark populated + remember old value
        el.setAttribute("data-was-populated", "1");
        //oldValueMap.set(el, real);
        if (!el.getAttribute("data-typed")) {
            oldValueMap.set(el, real);
        }

        var kind = classifyField(el);
        var masked = getMasked(kind, real);

        var wrap = ensureWrap(el);
        ensureNote(el, wrap);
        var shell = wrap.querySelector(".field-shell") || wrap;

        var overlay = shell.querySelector(".masked-overlay");
        if (!overlay) {
            overlay = document.createElement("span");
            overlay.className = "masked-overlay";
            overlay.setAttribute("aria-hidden", "true");
            shell.appendChild(overlay);

            // Clicking overlay = start editing; DO NOT reveal old value
            overlay.addEventListener("click", function (e) {
                if (!backtrackMode) return; // only on return visits
                e.preventDefault();
                e.stopPropagation();

                // el.setAttribute("data-typed", "0"); //redundant
                // IMPORTANT: do NOT set data-cleared here
                el.value = "";
                removeMask(el);
                //  showNote(el); // do not show here
                el.focus();
            });
        }

        overlay.textContent = masked;
        copyInputStylesToOverlay(el, overlay);

        el.classList.add("masked-value");
        hideNote(el);
    }

    function applyMasksIfBacktrack() {
        if (!backtrackMode) return;

        var fields = root.querySelectorAll("input, textarea");
        for (var i = 0; i < fields.length; i++) {
            var el = fields[i];

            if (!shouldMask(el)) continue;
            if (isInvalid(el)) continue;

            // Skip fields the user has already edited this visit
            if (el.getAttribute("data-typed") === "1") continue;

            if ((el.value || "").trim() !== "") {
                applyMask(el);
            }
        }
    }
    // ---------- Clear button ----------
    function addClearButton(el) {
        var wrap = ensureWrap(el);
        var shell = wrap.querySelector(".field-shell") || wrap;

        if (shell.querySelector(".clear-field-btn")) return;

        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "clear-field-btn";
        btn.setAttribute("aria-label", "Clear");
        btn.textContent = "×";

        btn.addEventListener("click", function (e) {
            e.preventDefault();
            e.stopPropagation();

            // Explicit clear = old mask should NOT return
            el.setAttribute("data-cleared", "1");
            el.setAttribute("data-typed", "1");

            // ✅ IMPORTANT: prevent restore forever
            oldValueMap.delete(el);
            el.removeAttribute("data-was-populated");


            el.value = "";
            el.dispatchEvent(new Event("input", { bubbles: true }));
            el.dispatchEvent(new Event("change", { bubbles: true }));

            removeMask(el);
            hideNote(el);
            showNote(el); //only show here
            el.focus();
        });

        shell.appendChild(btn);
    }

    // ---------- Wiring ----------
    function wire(el) {
        if (el.getAttribute("data-maskwired") === "1") return;
        el.setAttribute("data-maskwired", "1");

        if (!shouldMask(el)) return;

        // Always ensure structure + clear button exist (independent of backtrack mode)
        ensureWrap(el);
        addClearButton(el);

        // Track “typed this visit” (used by blur restore logic in backtrack mode)
        el.addEventListener("input", function () {
            el.setAttribute("data-typed", "1");


            // If this field was previously masked, drop that state now
            if (oldValueMap.has(el)) {
                oldValueMap.delete(el);
                removeMask(el);
            }

            // Only relevant when backtrack mode is active
            if (backtrackMode && (el.value || "").trim() !== "") {
                hideNote(el);
            }
        });

        // Backtrack-only: clicking/tapping into a masked field clears without revealing
        el.addEventListener("focus", function () {
            if (!backtrackMode) return;
            // Intentionally do nothing here
        });

        // Backtrack-only: restore old masked value if they didn't type and didn't click ✕
        el.addEventListener("blur", function () {
            if (!backtrackMode) return;

            var typed = el.getAttribute("data-typed") === "1";
            var wasCleared = el.getAttribute("data-cleared") === "1";
            var current = (el.value || "").trim();

            // If they did NOT type, field empty, and they did NOT click ✕: restore old value and re-mask
            if (!typed && !wasCleared && current === "") {
                var oldVal = oldValueMap.get(el) || "";
                if (oldVal.trim() !== "") {
                    el.value = oldVal;
                    applyMask(el);
                    hideNote(el);
                    return;
                }
            }

            // Mask whatever is there (if any), otherwise clean up
            if ((el.value || "").trim() !== "") {
                applyMask(el);
            } else {
                removeMask(el);

                // Only show “Please re-enter” if it was previously populated (your existing rule)
                //if (el.getAttribute("data-was-populated") === "1") {

            }

            // Reset cleared flag after blur (so it doesn’t persist)
            el.removeAttribute("data-cleared");

        });
    }

    function initWiring() {
        var fields = root.querySelectorAll("input, textarea");
        for (var i = 0; i < fields.length; i++) {
            wire(fields[i]); // creates wrappers + clear button + handlers (guarded by data-maskwired)
        }
    }

    // Always wire immediately; mask only on return visits (after hydration)
    initWiring();
    setTimeout(function () { initWiring(); applyMasksIfBacktrack(); }, 50);
    setTimeout(function () { initWiring(); applyMasksIfBacktrack(); }, 200);
    setTimeout(function () { initWiring(); applyMasksIfBacktrack(); }, 500);


})();

