// AI suggestion
(function () {

  const targetText = "Primary Contact workers";

  const tooltipHTML =
    "<i><b>A Primary Contact</b> worker mainly has direct contact with children. This may include but is not limited to educators, teachers, teachers’ assistants/aides, specialist teachers and therapists.</i>"

  // Create tooltip
  const tooltip = document.createElement("div");
  tooltip.style.position = "absolute";
  tooltip.style.display = "none";
  tooltip.style.zIndex = "10000";
  tooltip.style.background = "#fff";
  tooltip.style.border = "1px solid #ccc";
  tooltip.style.padding = "6px";
  tooltip.style.maxWidth = "300px";
  tooltip.style.fontSize = "13px";
  tooltip.style.boxShadow = "0 2px 6px rgba(0,0,0,0.2)";
  tooltip.innerHTML = tooltipHTML;

  document.body.appendChild(tooltip);

  function attachFirstOnly() {

    const walker = document.createTreeWalker(
      document.body,
      NodeFilter.SHOW_TEXT,
      null
    );

    let textNode;

    while ((textNode = walker.nextNode())) {

      if (textNode.nodeValue.includes(targetText)) {

        const parent = textNode.parentNode;
        const parts = textNode.nodeValue.split(targetText);

        parent.removeChild(textNode);
        parent.append(parts[0]);

        const span = document.createElement("span");
        span.textContent = targetText;
        span.style.cursor = "help";
        span.style.textDecoration = "underline";

        parent.appendChild(span);
        parent.append(parts[1]);

        // Hover events
        span.addEventListener("mouseenter", () => {
          tooltip.style.display = "block";
          const r = span.getBoundingClientRect();
          tooltip.style.left = r.left + window.scrollX + "px";
          tooltip.style.top = r.bottom + window.scrollY + 6 + "px";
        });

        span.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        return; // ✅ HARD STOP — first match only
      }
    }
  }

  // FORSTA renders late
  setTimeout(attachFirstOnly, 800);

})();


