    if (((dt > 10 && ((sum / dt) < 0.5) || ((sum / dt) > 1.5))) || ((dt >= 1 && dt <= 10) && (Math.abs(dt - sum) > 5))) {
        if (dt > 10 && ((sum / dt) < 0.5)) { test = (sum / dt) }
        if (dt > 10 && ((sum / dt) > 1.5)) { test = (sum / dt) }
        if ((dt >= 1 && dt <= 10) && (sum > dt + 5)) { test = (dt + 5) }
