function maskingB2() {

    var st = set(); // Initialize with an empty set, not a JavaScript Set object
    var qans = f('B1').domainValues()

    for (var i = 0; i < qans.length; i++) {
        var code = qans[i];
        if (f('B1').item(code) > 0) {
            st = st.union(set(code));
        }
    }
    return st;
}

