  $('#desktop_B5_2_text').attr('data-tooltip', "intentionally using senses to experience certain stimuli (e.g., watching, listening, touching, smelling and tasting); ability to imitate actions or behaviours; learning to read and write; ability to solve problems, make decisions or think; and ability to focus and maintain attention to specific stimuli or tasks.");
  $('#desktop_B5_2_text').addClass('b5tooltip');
  $('#desktop_B5_3_text').attr('data-tooltip', "understanding and/or responding to spoken messages or non-verbal messages such as symbols, signs or drawings; speaking and/or singing; making self understood in their most effective method of communication or language if applicable.");
  $('#desktop_B5_3_text').addClass('b5tooltip');
  $('#desktop_B5_4_text').attr('data-tooltip', "ability to roll, crawl, walk, climb and move around within and outside of buildings; being able to stay in the same body position (e.g. sitting and standing) to play or carry out a task; performing coordinated actions of handling objects (such as picking something up, grasping a toy or throwing).");
  $('#desktop_B5_4_text').addClass('b5tooltip');
  $('#desktop_B5_5_text').attr('data-tooltip', "caring for oneself by performing activities appropriate to age, such as washing and drying oneself, dressing, eating, drinking and toileting.");
  $('#desktop_B5_5_text').addClass('b5tooltip');
  $('#desktop_B5_6_text').attr('data-tooltip', "carrying out the tasks required for appropriate, basic and/or complex interactions with other people (including family members, friends, relatives, adults and strangers); creating and maintaining relationships in formal settings (such as child care centre); behaving within acceptable limits; responding to the feelings of others and coping with own emotions.");
  $('#desktop_B5_6_text').addClass('b5tooltip');
  $('#desktop_B5_7_text').attr('data-tooltip', "including general tasks (such as undertaking and carrying out single or multiple tasks or being able to follow and adapt to changes in routine or managing behaviours or emotions in completing tasks); domestic life; community and social life (such as ability to engage in groups or clubs for children that undertake activities such as play, games, sport and/or other hobbies).");
  $('#desktop_B5_7_text').addClass('b5tooltip');
})();

