// // *************************************


var qid = f("B5_1")
var qans = f("B5_1").domainValues()

var b2error3 = 0
var count = parseInt(f('B5_1_errCount').get(), 10) || 0; // Convert open-end to number
var countb = parseInt(f('B5_1_errCountb').get(), 10) || 0; // Convert open-end to number
var countc = parseInt(f('B5_1_errCountc').get(), 10) || 0; // Convert open-end to number

clearMulti('error_rows')
clearMulti('error_rows2')
clearMulti('error_rows3')


//f('q321').set(Get3DGridQuestionIds("B5").toString())

// *(PROGRAMMER NOTE: MUST ENTER AT LEAST ONE VALUE IN GRID TO PROCEED. IF NOT ANSWERED ALL CELLS AND ENTERED AT LEAST ONE VALUE, RECORD ALL OTHER VALUES AS 0.)
var qnames = Get3DGridQuestionIds("B5"); // B5_1 - B5_7
var hasValue = false;
qnames.forEach(q => {
    if (f(q).toBoolean()) hasValue = true;
});
if (hasValue) {

    var qset = String(a("B5")).split(","); // 1 - 13
    qnames.forEach(q => {
        for (var i = 1; i <= qset.length; i++) {
            if (!f(`${q}_${i}`).toBoolean()) {
                f(`${q}_${i}`).set(0);
            }
        }
    })

}else{
    RaiseError();
    ClearErrorMessage();
    ClearQuestionErrorMessage();
    SetQuestionErrorMessage(LangIDs.en_au, "Please provide one answer.");
}

// store sum of each b1 question
for (var b = 1; b <= 7; b++) {

    var colSum = 0;

    for (var item = 1; item <= 13; item++) {
        var val = f("B5_" + b + "_" + item).toNumber();

        if (!isNaN(val)) {
            colSum += val;
        }
    }

    f("SUM_B5_" + b).set(colSum);
}



// 1. check that sum of B5_2 to B5_7 is not lower than B5_1 (error_rows)
// 2. check that each individual cell value is not > B5_1 (error_rows2)
var precodes = f("B5_1").domainValues(); //array with all precodes
var error_rows = new Array();
var error_rows2 = new Array();
var error_rows3 = new Array();
for (var i = 0; i < precodes.length; i++) {
    var code = precodes[i]; //current precode
    //calculate the sum for the row: (B5_2 to B5_7)
    var sum = f("B5_2").item(code).toNumber() + f("B5_3").item(code).toNumber() + f("B5_4").item(code).toNumber() + f("B5_5").item(code).toNumber() + f("B5_6").item(code).toNumber() + f("B5_7").item(code).toNumber();
