// *(PROGRAMMER NOTE: IF lrstaff >5 AND Irstaff/D1a_Total < 0.5 or > 1.5. *SOFT CHECK – ALLOW THROUGH AFTER FLAGGED)
// ERROR MESSAGE: “Please check your response. At registration, it was estimated that your service had <Irstaff> individual workers during the reference week. If this is correct, click 'Next' to continue or change your response and click 'Next' to continue.”

var count = parseInt(f('D1a_errCount').get(), 10) || 0;
var d1aerror = false;
var ir = f('IRstaff').toNumber();
var d1aTotal = f('D1a').toNumber();

if (!isNaN(ir) && !isNaN(d1aTotal) && d1aTotal > 0) {
    if (ir > 5 && ((ir / d1aTotal < 0.5) || (ir / d1aTotal > 1.5))) {
        d1aerror = true
    }
}

if (d1aerror && count === 0) {
    f('D1a_errCount').set(count + 1)
    RaiseError();
    ClearErrorMessage();
    ClearQuestionErrorMessage();
    AppendQuestionErrorMessage(LangIDs.en_au, "Please check your response. At registration, it was estimated that your service had " + f('IRstaff').get() + " individual workers during the reference week. If this is correct, click 'Next' to continue or change your response and click 'Next' to continue.");

}

Script.ScriptCode:
var fdc = f('FDC_workers_last_submitted_dt').toNumber();
var d1aTotal = f('D1a').toNumber();
var d1vCheck = false;
var d1xCheck = false;
var sumB1 = Sum(f('B1').values());
var fdcRatio = NaN;
var contactRatio = NaN;

// COMPUTE DUMMY VARIABLE CONTACT_RATIO = B1 TOTAL / D1a_Total.

if (d1aTotal > 0) {
    contactRatio = (sumB1 / d1aTotal).toFixed(2)
    f('CONTACT_RATIO').set(contactRatio)

    // *((CONTACT_RATIO<2 OR >15) AND SERVICE_TYPE<>12, RATIO TOO HIGH OR LOW AND NOT A PRESCHOOL)
    if ((contactRatio < 2 || contactRatio > 15) && f('service_type').none('12')) {
        d1xCheck = true;
    }
}

if (d1xCheck) {
    f('D1X_ask').set('1')
}

// *(SERVICE_TYPE=2 FDC)
// COMPUTE DUMMY VARIABLE FDC_RATIO = (D1a_Total – FDC_workers_last_submitted_dt) / FDC_workers_last_submitted_dt

// *(FDC_workers_last_submitted_dt > 10 and < 50) AND (FDC_RATIO) < -0.5 OR > 1.5)
// *(FDC_workers_last_submitted_dt >= 50) AND (FDC_RATIO) < -0.3 OR > 1.7)
// *(FDC_workers_last_submitted_dt > 0 and <=10 and (D1a_Total ± 5 from FDC_workers_last_submitted_dt))

if (fdc > 0 && d1aTotal > 0) {
    fdcRatio = ((d1aTotal - fdc) / fdc).toFixed(2)
    f('FDC_RATIO').set(fdcRatio)


    if (((fdc > 10 && fdc < 50) && ((fdcRatio < -0.5) || fdcRatio > 1.5)) ||
        (fdc >= 50 && (fdcRatio < -0.3 || fdcRatio > 1.7)) ||
        ((fdc > 0 && fdc <= 10) && (Math.abs(d1aTotal - fdc) > 5))) {
        d1vCheck = true;
    }
}

f('D1a').set(null);
f('D1V_ask').set(null);

if (GetSurveyChannel()=="Cawi" && f('Mode').any('1')) {
    Redirect(GetRespondentUrl("D1a",false),true);
}
else {
    Redirect(GetCatiRespondentUrl("D1a"));
}

// f('B1').set(null);
f('D1X_ask').set(null);

if (GetSurveyChannel()=="Cawi" && f('Mode').any('1')) {
    Redirect(GetRespondentUrl("B1",false),true);
}
else {
    Redirect(GetCatiRespondentUrl("B1"));
}

f('D1a').set(null);
f('D1X_ask').set(null);

if (GetSurveyChannel()=="Cawi" && f('Mode').any('1')) {
    Redirect(GetRespondentUrl("D1a",false),true);
}
else {
    Redirect(GetCatiRespondentUrl("D1a"));
}

